//! Byte equality against the real upstream generator (required in the oracle CI job).
mod common;
use cdht::{Descriptor, EncryptionKey, Schema, SignedValue, Signer};
use common::{TestVerifier, key};
use data_encoding::BASE64URL_NOPAD;
use serde_json::Value;

fn bytes(v: &Value) -> Vec<u8> {
    BASE64URL_NOPAD
        .decode(v.as_str().unwrap().as_bytes())
        .unwrap()
}

#[test]
#[ignore = "requires vectors generated by pinned Veilid; required in the conformance CI job"]
fn upstream_vectors() {
    let path = std::env::var("CDHT_VECTORS").expect("run ci/veilid-vectors.sh on CI");
    let vectors: Value = serde_json::from_slice(&std::fs::read(path).unwrap()).unwrap();
    assert_eq!(
        vectors["commit"],
        "dd8e2cdd72b5bf817172ac31c20872b168c5c8fc"
    );
    let owner = key(1);
    let writer = key(2);
    assert_eq!(owner.public_key().as_slice(), bytes(&vectors["owner"]));
    assert_eq!(writer.public_key().as_slice(), bytes(&vectors["writer"]));
    let operation = cdht::rpc::SignedOperation::sign(
        bytes(&vectors["rpcOperation"]),
        &writer.public_key(),
        &owner,
    )
    .unwrap();
    assert_eq!(operation.as_bytes(), bytes(&vectors["rpcPacket"]));
    cdht::rpc::SignedOperation::verify(
        bytes(&vectors["rpcPacket"]),
        &writer.public_key(),
        &owner.public_key(),
        &TestVerifier,
    )
    .unwrap();
    for vector in vectors["schemas"].as_array().unwrap() {
        let compiled = bytes(&vector["schema"]);
        let schema = Schema::parse(&compiled).unwrap();
        assert_eq!(schema.compile(), compiled);
        assert_eq!(
            schema.subkey_count() as u64,
            vector["count"].as_u64().unwrap()
        );
        let descriptor = Descriptor::create(&schema, &owner).unwrap();
        assert_eq!(
            descriptor.key().to_string(),
            vector["key"].as_str().unwrap()
        );
        assert_eq!(descriptor.signature.as_slice(), bytes(&vector["signature"]));
        assert_eq!(
            cdht::rpc::DescriptorBytes::encode(&descriptor)
                .unwrap()
                .as_bytes(),
            bytes(&vector["rpcDescriptor"])
        );
    }
    let schema = Schema::parse(&bytes(&vectors["schema"])).unwrap();
    let record = Descriptor::create(&schema, &owner).unwrap().key();
    let secret = EncryptionKey::from_bytes([42; 32]);
    assert_eq!(
        secret.record_key(&record).as_str(),
        vectors["full_key"].as_str().unwrap()
    );
    let (parsed, parsed_secret) =
        EncryptionKey::parse_record_key(vectors["full_key"].as_str().unwrap()).unwrap();
    assert_eq!(parsed, record);
    for vector in vectors["values"].as_array().unwrap() {
        let nonce = vector["encrypted"].as_bool().unwrap().then_some([3; 24]);
        let plaintext = bytes(&vector["plaintext"]);
        let data = match nonce {
            Some(n) => parsed_secret
                .as_ref()
                .unwrap()
                .crypt(&n, &plaintext)
                .unwrap()
                .to_vec(),
            None => plaintext.clone(),
        };
        assert_eq!(data, bytes(&vector["data"]));
        let value = SignedValue::sign_with_nonce(
            &owner.public_key(),
            1,
            vector["seq"].as_u64().unwrap() as u32,
            data,
            nonce,
            &writer,
        )
        .unwrap();
        assert_eq!(value.raw_blob().unwrap(), bytes(&vector["blob"]));
        assert_eq!(value.signature.as_slice(), bytes(&vector["signature"]));
        assert_eq!(
            cdht::rpc::ValueBytes::encode(&value).unwrap().as_bytes(),
            bytes(&vector["rpcValue"])
        );
        let descriptor = Descriptor::create(&schema, &owner).unwrap();
        for (request, response, expected) in [
            (
                bytes(&vectors["rpcOperation"]),
                cdht::rpc::Response::Get {
                    accepted: true,
                    value: Some(Box::new(value.clone())),
                    descriptor: Some(descriptor),
                    peers: vec![],
                },
                "getAnswer",
            ),
            (
                bytes(&vector["setQuestion"]),
                cdht::rpc::Response::Set {
                    accepted: false,
                    need_descriptor: false,
                    value: Some(Box::new(value.clone())),
                    peers: vec![],
                },
                "setAnswer",
            ),
        ] {
            let question =
                cdht::rpc::SignedOperation::sign(request, &writer.public_key(), &owner).unwrap();
            assert_eq!(
                cdht::rpc::Answer::new(&question, &response)
                    .unwrap()
                    .as_bytes(),
                bytes(&vector[expected])
            );
        }
        let decoded = SignedValue::from_blob(bytes(&vector["blob"]), value.signature).unwrap();
        decoded
            .validate(&record, &owner.public_key(), &schema, 1, &TestVerifier)
            .unwrap();
        assert_eq!(decoded.raw_blob().unwrap(), value.raw_blob().unwrap());
        assert!(decoded.same_value(&value));
        let mut tampered = decoded;
        tampered.nonce = Some([8; 24]);
        assert!(
            tampered
                .validate(&record, &owner.public_key(), &schema, 1, &TestVerifier)
                .is_err()
        );
    }
}
